const inp = $input.first().json;
const b = inp.body || inp;
const m = b.message || b;
const meta = (m.call && m.call.metadata) || m.metadata || {};
const analysis = m.analysis || {};
const sd = analysis.structuredData || {};
const transcript = m.transcript || '';
const connected = !!transcript && (sd.connected !== false);
const firma = String(meta.firma || 'Unbekannt').replace(/[\\/:*?"<>|]/g, '').trim() || 'Unbekannt';
const d = new Date();
const pad = (n) => String(n).padStart(2, '0');
const ts = `${d.getFullYear()}${pad(d.getMonth()+1)}${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}`;
const il = sd.interest_level;
const outcome = il === 'hot' ? 'Hot' : il === 'warm' ? 'Borderline' : (connected ? 'Cold' : 'Direct-Abwimmlung');
return [{ json: {
  connected,
  transcript,
  drive_filename: `${firma}__joaquin.m4a_${ts}.txt`,
  session_id: meta.session_id || '',
  cost: m.cost || 0,
  endedReason: m.endedReason || '',
  app_payload: { lead_id: meta.lead_id || '', firma: meta.firma || '', branche: meta.branche || '', disclose_ai: !!meta.disclose_ai, transcript, outcome, analysis: sd }
} }];

// Voicemail / no-answer: light log only, no Drive drop, retry-eligible.
const j = $input.first().json;
return [{ json: { logged: true, endedReason: j.endedReason, note: 'not connected / no transcript' } }];
